$projects = Get-ChildItem "$env:USERPROFILE\.cursor\projects" -Directory
$rows = foreach ($p in $projects) {
  $tDir = Join-Path $p.FullName 'agent-transcripts'
  if (-not (Test-Path $tDir)) { continue }
  Get-ChildItem $tDir -Directory | ForEach-Object {
    $jsonl = Join-Path $_.FullName ($_.Name + '.jsonl')
    $title = ''
    if (Test-Path $jsonl) {
      $first = Get-Content $jsonl -TotalCount 8 -ErrorAction SilentlyContinue
      foreach ($line in $first) {
        if ($line -match '"title"\s*:\s*"([^"]+)"') { $title = $Matches[1]; break }
      }
      if (-not $title) {
        foreach ($line in $first) {
          if ($line -match '"role"\s*:\s*"user"') {
            if ($line -match '"text"\s*:\s*"([^"]{8,80})') { $title = $Matches[1]; break }
            if ($line -match '"content"\s*:\s*"([^"]{8,80})') { $title = $Matches[1]; break }
          }
        }
      }
    }
    [PSCustomObject]@{
      Project = $p.Name
      Id = $_.Name
      Title = $title
      LastWrite = $_.LastWriteTime
      Created = $_.CreationTime
      SizeKB = [math]::Round(((Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum / 1KB), 1)
    }
  }
}
$rows | Sort-Object LastWrite -Descending | ConvertTo-Csv -NoTypeInformation

$roots = @(
  "$env:APPDATA\Cursor",
  "$env:USERPROFILE\.cursor",
  "$env:LOCALAPPDATA\Cursor"
)
foreach ($r in $roots) {
  if (Test-Path $r) {
    Write-Host "=== $r ==="
    Get-ChildItem $r -Directory -ErrorAction SilentlyContinue | Select-Object Name, LastWriteTime | Format-Table -AutoSize | Out-String | Write-Host
  }
}
Write-Host '--- search cloudAgent / composer ---'
Get-ChildItem "$env:APPDATA\Cursor" -Recurse -File -ErrorAction SilentlyContinue |
  Where-Object { $_.Name -match 'cloudAgent|composer|aichat|conversation|agent' -and $_.Length -lt 50MB } |
  Select-Object -First 80 FullName, Length, LastWriteTime

$out = @()
# Pull broad keyword sweeps into one unique set via PowerShell + known SearchConversations can't be called here; use transcript dirs + sqlite if possible
# Query state.vscdb for composer/conversation keys (read-only, limit)

$db = "$env:APPDATA\Cursor\User\globalStorage\state.vscdb"
$sqlite = Get-Command sqlite3 -ErrorAction SilentlyContinue
if (-not $sqlite) {
  # try common locations
  $candidates = @(
    'C:\Program Files\SQLite\sqlite3.exe',
    "$env:LOCALAPPDATA\Programs\Git\usr\bin\sqlite3.exe"
  )
  foreach ($c in $candidates) { if (Test-Path $c) { $sqlite = $c; break } }
}

Write-Host "sqlite: $sqlite"

# Build unique agent list from transcript folders (canonical last-write per id)
$map = @{}
Get-ChildItem "$env:USERPROFILE\.cursor\projects" -Directory | ForEach-Object {
  $tDir = Join-Path $_.FullName 'agent-transcripts'
  if (-not (Test-Path $tDir)) { return }
  Get-ChildItem $tDir -Directory | ForEach-Object {
    $id = $_.Name
    $lw = $_.LastWriteTimeUtc
    $proj = $_.Parent.Parent.Name
    if (-not $map.ContainsKey($id) -or $lw -gt $map[$id].LastWriteUtc) {
      $map[$id] = [PSCustomObject]@{
        Id = $id
        Project = $proj
        LastWriteUtc = $lw
        SizeMB = [math]::Round(((Get-ChildItem $_.FullName -Recurse -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum / 1MB), 2)
      }
    }
  }
}

# Titles from conversation index file if any
$indexHints = @{}

$map.Values | Sort-Object LastWriteUtc -Descending | ForEach-Object {
  '{0:yyyy-MM-dd HH:mm}Z | {1} MB | {2} | {3}' -f $_.LastWriteUtc, $_.SizeMB, $_.Id, $_.Project
} | Set-Content -Encoding utf8 "$env:TEMP\agent-list-by-date.txt"
(Get-Content "$env:TEMP\agent-list-by-date.txt").Count
Get-Content "$env:TEMP\agent-list-by-date.txt" | Select-Object -First 120
Write-Host '---TOTAL---'
(Get-Item "$env:TEMP\agent-list-by-date.txt").FullName
# disk usage
$totalMB = ($map.Values | Measure-Object SizeMB -Sum).Sum
Write-Host "unique=$($map.Count) totalMB=$([math]::Round($totalMB,1))"
# cloud branches with last commit date
Push-Location 'A:\Dark Matter Genesis'
git for-each-ref --sort=-committerdate --format='%(committerdate:short) | %(refname:short)' refs/remotes/origin/cursor refs/heads/cursor 2>$null | Select-Object -First 50
Pop-Location

$paths = @(
  "$env:APPDATA\Cursor\User\globalStorage\state.vscdb",
  "$env:APPDATA\Cursor\User\globalStorage\state.vscdb.bak-ghost-purge-1785025821",
  "$env:APPDATA\Cursor\User\globalStorage\state.vscdb-wal",
  "$env:USERPROFILE\.cursor\projects"
)
foreach ($p in $paths) {
  if (Test-Path $p) {
    $item = Get-Item $p
    if ($item.PSIsContainer) {
      $sum = (Get-ChildItem $p -Recurse -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum
      '{0:N1} GB  {1}' -f ($sum/1GB), $p
    } else {
      '{0:N1} GB  {1}' -f ($item.Length/1GB), $p
    }
  }
}
Write-Host '--- transcript total ---'
$t = 0
Get-ChildItem "$env:USERPROFILE\.cursor\projects" -Directory | ForEach-Object {
  $td = Join-Path $_.FullName 'agent-transcripts'
  if (Test-Path $td) {
    $t += (Get-ChildItem $td -Recurse -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum
  }
}
'{0:N1} MB transcripts' -f ($t/1MB)
Write-Host '--- Cursor Cache folders ---'
@("$env:APPDATA\Cursor\Cache","$env:APPDATA\Cursor\CachedData","$env:APPDATA\Cursor\GPUCache","$env:APPDATA\Cursor\Code Cache","$env:APPDATA\Cursor\logs") | ForEach-Object {
  if (Test-Path $_) {
    $s = (Get-ChildItem $_ -Recurse -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum
    '{0:N0} MB  {1}' -f ($s/1MB), $_
  }
}

$bak = Get-ChildItem "$env:APPDATA\Cursor\User\globalStorage" -Filter "state.vscdb.bak-ghost-purge-*" -File -ErrorAction SilentlyContinue
if (-not $bak) { Write-Host 'No backup file found.'; exit 0 }
$bak | ForEach-Object {
  '{0:N2} GB  {1}' -f ($_.Length/1GB), $_.FullName
  '{0:yyyy-MM-dd HH:mm}' -f $_.LastWriteTime
}
# Confirm live DB still present
$live = "$env:APPDATA\Cursor\User\globalStorage\state.vscdb"
Write-Host "live exists: $(Test-Path $live) sizeGB: $([math]::Round((Get-Item $live).Length/1GB,1))"
# Delete backups only
foreach ($f in $bak) {
  Remove-Item -LiteralPath $f.FullName -Force
  Write-Host "Deleted: $($f.Name)  remaining: $(-not (Test-Path $f.FullName))"
}
Write-Host '--- after ---'
Get-ChildItem "$env:APPDATA\Cursor\User\globalStorage" -Filter "state.vscdb*" | ForEach-Object {
  '{0:N2} GB  {1}' -f ($_.Length/1GB), $_.Name
}

