using Project.Combat;
using Project.Data;
using Project.Interaction;
using UnityEditor;
using UnityEngine;

namespace Project.EditorTools
{
    /// <summary>
    /// Shared UI + create logic for Crafting Item Creator (embedded in Blueprint and Crafting Manager).
    /// Fields shown depend on <see cref="ItemType"/> — same groupings as <see cref="ItemDataEditor"/>.
    /// </summary>
    public sealed class CraftingItemCreatorPanel
    {
        private string itemName = "New Crafting Item";
        private string assetFileName = string.Empty;
        private ItemType itemType = ItemType.Resource;
        private ItemType lastDrawnType = ItemType.Resource;
        private int maxStack = 64;
        private string tooltipDescription = string.Empty;
        private Sprite icon;
        private GameObject worldPrefabTemplate;
        private bool createWorldPrefab = true;
        private bool addToItemRegistry = true;

        // Consumable
        private float healthRestore;
        private float energyRestore;
        private float staminaRestore;
        private float oxygenRestore;

        // Resource / craft scrap
        private ComponentCategory componentCategory = ComponentCategory.None;

        // Equipment shared (melee / ranged / tool)
        private WeaponGrip weaponGrip = WeaponGrip.OneHanded;
        private GameObject heldPrefab;
        private string equipSocketName = "RightHand";
        private GameObject invectorWeaponPrefab;
        private string invectorWeaponId = string.Empty;

        // Melee
        private float meleeDamage = 10f;
        private float meleeDamageRandomRange = 3f;
        private float criticalChance = 0.1f;
        private float criticalDamageMultiplier = 2f;
        private float meleeRange = 2.2f;
        private float meleeCooldown = 0.65f;
        private float meleeStaminaCost;
        private int gatherPower = 1;
        private string attackTrigger = "Attack";
        private Vector3 swingEulerAngles = new Vector3(-120f, 0f, 0f);

        // Ranged
        private float rangedDamage = 14f;
        private float rangedDamageRandomRange = 4f;
        private float rangedRange = 45f;
        private float projectileSpeed = 85f;
        private float projectileSpreadDegrees = 1.5f;
        private float weaponAccuracy = 75f;
        private float fireRate = 4f;
        private int magazineSize = 30;
        private float reloadTimeSeconds = 1.8f;
        private AmmoType defaultAmmoType = AmmoType.Gunpowder;
        private ItemData defaultAmmoItem;
        private GameObject projectilePrefab;
        private string muzzleSocketName = "Muzzle";
        private bool isMiningTool;

        // Mining (when ranged + isMiningTool)
        private int miningPassesRequired = 2;
        private int miningDropMin = 1;
        private int miningDropMax = 5;
        private float miningPassDuration = 1.25f;
        private float miningChargeDrainPerSecond = 4f;
        private float miningChargePerPlasmaFuel = 50f;

        // Ammo
        private AmmoType ammoType = AmmoType.Gunpowder;
        private int ammoPerPickup = 20;
        private float ammoPickupGrant = 20f;
        private bool isHitscanBeam;
        private float splashRadius;

        // Tool
        private ToolType toolType = ToolType.None;
        private float toolRange = 8f;
        private float scanRange = 24f;
        private float opticsZoomFov = 38f;
        private float opticsMinZoomFov = 18f;
        private float opticsMaxZoomFov = 55f;

        // Vehicle
        private GameObject deployedPrefab;

        // Module flag (consumable/resource authoring convenience)
        private bool unlocksInventoryStorageRow;

        private Vector2 scroll;

        public void Draw()
        {
            scroll = EditorGUILayout.BeginScrollView(scroll);

            EditorGUILayout.LabelField("Crafting Item Creator", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox(
                "Create ItemData for blueprint ingredients and crafted outputs.\n" +
                "Choose Item Type to show only fields for that type.\n" +
                "Grenades: use Grenade / Throwable Item Creator. Advanced weapons: Equipment / Ammo creators still available.",
                MessageType.None);
            EditorGUILayout.Space(8f);

            itemName = EditorGUILayout.TextField("Item Name", itemName);
            assetFileName = EditorGUILayout.TextField(
                "Asset File Name",
                string.IsNullOrEmpty(assetFileName) ? CraftingEditorUtility.SanitizeAssetName(itemName) : assetFileName);

            EditorGUI.BeginChangeCheck();
            itemType = (ItemType)EditorGUILayout.EnumPopup("Item Type", itemType);
            if (EditorGUI.EndChangeCheck() || itemType != lastDrawnType)
            {
                ApplyTypeDefaults(itemType);
                lastDrawnType = itemType;
            }

            maxStack = EditorGUILayout.IntField("Max Stack", Mathf.Max(1, maxStack));
            icon = (Sprite)EditorGUILayout.ObjectField("Icon", icon, typeof(Sprite), false);

            DrawTypeSpecificFields();

            EditorGUILayout.Space(8f);
            EditorGUILayout.LabelField("Tooltip", EditorStyles.boldLabel);
            tooltipDescription = EditorGUILayout.TextArea(tooltipDescription, GUILayout.MinHeight(48f));

            EditorGUILayout.Space(8f);
            EditorGUILayout.LabelField("World Pickup", EditorStyles.boldLabel);
            createWorldPrefab = EditorGUILayout.Toggle("Create World Prefab", createWorldPrefab);
            using (new EditorGUI.DisabledScope(!createWorldPrefab))
            {
                worldPrefabTemplate = (GameObject)EditorGUILayout.ObjectField(
                    "Mesh Template", worldPrefabTemplate, typeof(GameObject), false);
            }

            addToItemRegistry = EditorGUILayout.Toggle("Add To Item Registry", addToItemRegistry);

            EditorGUILayout.Space(16f);
            using (new EditorGUI.DisabledScope(string.IsNullOrWhiteSpace(itemName)))
            {
                if (GUILayout.Button("Create Crafting Item", GUILayout.Height(42f)))
                    CreateItem();
            }

            EditorGUILayout.EndScrollView();
        }

        private void ApplyTypeDefaults(ItemType type)
        {
            switch (type)
            {
                case ItemType.MeleeWeapon:
                case ItemType.RangedWeapon:
                case ItemType.Tool:
                case ItemType.Vehicle:
                case ItemType.Quest:
                    maxStack = 1;
                    break;
                case ItemType.Ammo:
                    maxStack = Mathf.Max(maxStack, 20);
                    break;
                default:
                    if (maxStack < 2)
                        maxStack = 64;
                    break;
            }
        }

        private void DrawTypeSpecificFields()
        {
            EditorGUILayout.Space(8f);

            switch (itemType)
            {
                case ItemType.Consumable:
                    DrawConsumableFields();
                    break;
                case ItemType.Resource:
                    DrawResourceFields();
                    break;
                case ItemType.MeleeWeapon:
                    DrawMeleeFields();
                    break;
                case ItemType.RangedWeapon:
                    DrawRangedFields();
                    break;
                case ItemType.Ammo:
                    DrawAmmoFields();
                    break;
                case ItemType.Tool:
                    DrawToolFields();
                    break;
                case ItemType.Quest:
                    EditorGUILayout.HelpBox(
                        "Quest items are identity-only (name, icon, tooltip, pickup). No combat or restore stats.",
                        MessageType.Info);
                    break;
                case ItemType.Vehicle:
                    DrawVehicleFields();
                    break;
            }
        }

        private void DrawConsumableFields()
        {
            EditorGUILayout.LabelField("Survival Restore", EditorStyles.boldLabel);
            healthRestore = EditorGUILayout.FloatField("Health", healthRestore);
            energyRestore = EditorGUILayout.FloatField("Energy", energyRestore);
            staminaRestore = EditorGUILayout.FloatField("Stamina", staminaRestore);
            oxygenRestore = EditorGUILayout.FloatField("Oxygen (display sec)", oxygenRestore);
            EditorGUILayout.Space(4f);
            unlocksInventoryStorageRow = EditorGUILayout.Toggle(
                new GUIContent("Unlocks Inventory Row", "Marks this as an inventory expansion module."),
                unlocksInventoryStorageRow);
        }

        private void DrawResourceFields()
        {
            EditorGUILayout.LabelField("Craft Components", EditorStyles.boldLabel);
            componentCategory = (ComponentCategory)EditorGUILayout.EnumPopup(
                new GUIContent("Component Category", "None = plain resource. Scrap/Unique routes to Components folder when set."),
                componentCategory);
            EditorGUILayout.Space(4f);
            unlocksInventoryStorageRow = EditorGUILayout.Toggle(
                new GUIContent("Unlocks Inventory Row", "Marks this as an inventory expansion module."),
                unlocksInventoryStorageRow);
        }

        private void DrawEquipmentShared(bool includeSwing)
        {
            EditorGUILayout.LabelField("Equipment", EditorStyles.boldLabel);
            weaponGrip = (WeaponGrip)EditorGUILayout.EnumPopup("Weapon Grip", weaponGrip);
            heldPrefab = (GameObject)EditorGUILayout.ObjectField("Held Prefab", heldPrefab, typeof(GameObject), false);
            equipSocketName = EditorGUILayout.TextField("Equip Socket", equipSocketName);
            if (includeSwing)
                swingEulerAngles = EditorGUILayout.Vector3Field("Swing Euler", swingEulerAngles);

            EditorGUILayout.Space(4f);
            EditorGUILayout.LabelField("Invector", EditorStyles.boldLabel);
            invectorWeaponPrefab = (GameObject)EditorGUILayout.ObjectField(
                "Invector Weapon Prefab", invectorWeaponPrefab, typeof(GameObject), false);
            invectorWeaponId = EditorGUILayout.TextField("Invector Weapon Id", invectorWeaponId);
        }

        private void DrawMeleeFields()
        {
            DrawEquipmentShared(includeSwing: true);
            EditorGUILayout.Space(8f);
            EditorGUILayout.LabelField("Melee Base Stats", EditorStyles.boldLabel);
            meleeDamage = EditorGUILayout.FloatField("Damage", meleeDamage);
            meleeDamageRandomRange = EditorGUILayout.FloatField("Damage Random Range", meleeDamageRandomRange);
            criticalChance = EditorGUILayout.Slider("Critical Chance", criticalChance, 0f, 1f);
            criticalDamageMultiplier = EditorGUILayout.FloatField("Critical Multiplier", criticalDamageMultiplier);
            meleeRange = EditorGUILayout.FloatField("Range", meleeRange);
            meleeCooldown = EditorGUILayout.FloatField("Cooldown", meleeCooldown);
            meleeStaminaCost = EditorGUILayout.FloatField("Stamina Cost", meleeStaminaCost);
            gatherPower = EditorGUILayout.IntField("Gather Power", Mathf.Max(0, gatherPower));
            attackTrigger = EditorGUILayout.TextField("Attack Trigger", attackTrigger);
        }

        private void DrawRangedFields()
        {
            DrawEquipmentShared(includeSwing: false);
            EditorGUILayout.Space(8f);
            isMiningTool = EditorGUILayout.Toggle(
                new GUIContent("Is Mining Tool", "Hold-fire drives mining laser instead of combat shots."),
                isMiningTool);

            if (isMiningTool)
            {
                EditorGUILayout.Space(4f);
                EditorGUILayout.LabelField("Mining Tool", EditorStyles.boldLabel);
                miningPassesRequired = EditorGUILayout.IntField("Passes Required", Mathf.Max(1, miningPassesRequired));
                miningDropMin = EditorGUILayout.IntField("Drop Min", Mathf.Max(0, miningDropMin));
                miningDropMax = EditorGUILayout.IntField("Drop Max", Mathf.Max(miningDropMin, miningDropMax));
                miningPassDuration = EditorGUILayout.FloatField("Pass Duration (s)", Mathf.Max(0.05f, miningPassDuration));
                miningChargeDrainPerSecond = EditorGUILayout.FloatField("Charge Drain /s", miningChargeDrainPerSecond);
                miningChargePerPlasmaFuel = EditorGUILayout.FloatField("Charge Per Plasma Fuel", miningChargePerPlasmaFuel);
                return;
            }

            EditorGUILayout.Space(4f);
            EditorGUILayout.LabelField("Ranged Base Stats", EditorStyles.boldLabel);
            rangedDamage = EditorGUILayout.FloatField("Damage", rangedDamage);
            rangedDamageRandomRange = EditorGUILayout.FloatField("Damage Random Range", rangedDamageRandomRange);
            rangedRange = EditorGUILayout.FloatField("Range", rangedRange);
            projectileSpeed = EditorGUILayout.FloatField("Projectile Speed", projectileSpeed);
            projectileSpreadDegrees = EditorGUILayout.FloatField("Spread (deg)", projectileSpreadDegrees);
            weaponAccuracy = EditorGUILayout.Slider("Accuracy", weaponAccuracy, 0f, 100f);
            fireRate = EditorGUILayout.FloatField("Fire Rate", fireRate);
            magazineSize = EditorGUILayout.IntField("Magazine Size", Mathf.Max(1, magazineSize));
            reloadTimeSeconds = EditorGUILayout.FloatField("Reload Time (s)", reloadTimeSeconds);
            defaultAmmoType = (AmmoType)EditorGUILayout.EnumPopup("Default Ammo Type", defaultAmmoType);
            defaultAmmoItem = (ItemData)EditorGUILayout.ObjectField("Default Ammo Item", defaultAmmoItem, typeof(ItemData), false);
            projectilePrefab = (GameObject)EditorGUILayout.ObjectField("Projectile Prefab", projectilePrefab, typeof(GameObject), false);
            muzzleSocketName = EditorGUILayout.TextField("Muzzle Socket", muzzleSocketName);
        }

        private void DrawAmmoFields()
        {
            EditorGUILayout.LabelField("Ammo", EditorStyles.boldLabel);
            ammoType = (AmmoType)EditorGUILayout.EnumPopup("Ammo Type", ammoType);
            ammoPerPickup = EditorGUILayout.IntField("Ammo Per Pickup", Mathf.Max(1, ammoPerPickup));
            ammoPickupGrant = EditorGUILayout.FloatField("Ammo Pickup Grant", ammoPickupGrant);
            rangedDamage = EditorGUILayout.FloatField("Damage Override", rangedDamage);
            rangedDamageRandomRange = EditorGUILayout.FloatField("Damage Random Range", rangedDamageRandomRange);
            rangedRange = EditorGUILayout.FloatField("Range Override", rangedRange);
            projectileSpeed = EditorGUILayout.FloatField("Projectile Speed", projectileSpeed);
            projectileSpreadDegrees = EditorGUILayout.FloatField("Spread (deg)", projectileSpreadDegrees);
            weaponAccuracy = EditorGUILayout.Slider("Accuracy Override", weaponAccuracy, 0f, 100f);
            projectilePrefab = (GameObject)EditorGUILayout.ObjectField("Projectile Prefab", projectilePrefab, typeof(GameObject), false);

            EditorGUILayout.Space(4f);
            EditorGUILayout.LabelField("Projectile Behavior", EditorStyles.boldLabel);
            isHitscanBeam = EditorGUILayout.Toggle("Hitscan Beam", isHitscanBeam);
            splashRadius = EditorGUILayout.FloatField("Splash Radius", splashRadius);
        }

        private void DrawToolFields()
        {
            EditorGUILayout.LabelField("Equipment", EditorStyles.boldLabel);
            heldPrefab = (GameObject)EditorGUILayout.ObjectField("Held Prefab", heldPrefab, typeof(GameObject), false);
            equipSocketName = EditorGUILayout.TextField("Equip Socket", equipSocketName);

            EditorGUILayout.Space(4f);
            EditorGUILayout.LabelField("Tools", EditorStyles.boldLabel);
            toolType = (ToolType)EditorGUILayout.EnumPopup("Tool Type", toolType);
            toolRange = EditorGUILayout.FloatField("Tool Range", toolRange);

            bool optics = toolType == ToolType.Scanner || toolType == ToolType.Binoculars;
            if (optics)
            {
                scanRange = EditorGUILayout.FloatField("Scan Range", scanRange);
                opticsZoomFov = EditorGUILayout.FloatField("Optics Zoom FOV", opticsZoomFov);
                opticsMinZoomFov = EditorGUILayout.FloatField("Min Zoom FOV", opticsMinZoomFov);
                opticsMaxZoomFov = EditorGUILayout.FloatField("Max Zoom FOV", opticsMaxZoomFov);
            }
        }

        private void DrawVehicleFields()
        {
            EditorGUILayout.LabelField("Deployable / Vehicle", EditorStyles.boldLabel);
            deployedPrefab = (GameObject)EditorGUILayout.ObjectField(
                new GUIContent("Deployed Prefab", "Spawned when Deployed from inventory (e.g. hovercraft)."),
                deployedPrefab,
                typeof(GameObject),
                false);
        }

        private void CreateItem()
        {
            string safeName = CraftingEditorUtility.SanitizeAssetName(
                string.IsNullOrWhiteSpace(assetFileName) ? itemName : assetFileName);
            if (string.IsNullOrEmpty(safeName))
            {
                EditorUtility.DisplayDialog("Crafting Item Creator", "Enter a valid item or file name.", "OK");
                return;
            }

            ItemData draftForFolder = ScriptableObject.CreateInstance<ItemData>();
            draftForFolder.itemType = itemType;
            draftForFolder.componentCategory = componentCategory;
            draftForFolder.unlocksInventoryStorageRow = unlocksInventoryStorageRow;
            draftForFolder.isMiningTool = isMiningTool;
            draftForFolder.toolType = toolType;
            string folder = CraftingEditorUtility.GetItemCategoryFolder(draftForFolder);
            Object.DestroyImmediate(draftForFolder);

            CraftingEditorUtility.EnsureFolder(folder);
            CraftingEditorUtility.EnsureFolder(ProjectAssetPaths.PrefabsItemsWorld);

            string dataPath = $"{folder}/{safeName}.asset";
            if (AssetDatabase.LoadAssetAtPath<ItemData>(dataPath) != null
                && !EditorUtility.DisplayDialog(
                    "Crafting Item Creator",
                    $"Item asset '{safeName}' already exists. Overwrite?",
                    "Overwrite",
                    "Cancel"))
            {
                return;
            }

            ItemData item = AssetDatabase.LoadAssetAtPath<ItemData>(dataPath);
            if (item == null)
            {
                item = ScriptableObject.CreateInstance<ItemData>();
                AssetDatabase.CreateAsset(item, dataPath);
            }

            ApplyIdentity(item);
            ApplyTypeData(item);

            ItemDataPruneUtility.Prune(item);
            EditorUtility.SetDirty(item);

            if (createWorldPrefab && worldPrefabTemplate != null)
                CreateWorldPickup(item, safeName);

            if (addToItemRegistry)
                CraftingEditorUtility.AddItemToRegistry(item);

            AssetDatabase.SaveAssets();

            Selection.activeObject = item;
            EditorGUIUtility.PingObject(item);
            EditorUtility.DisplayDialog("Crafting Item Creator", $"Created crafting item '{item.itemName}'.", "OK");
        }

        private void ApplyIdentity(ItemData item)
        {
            item.itemName = itemName.Trim();
            item.itemType = itemType;
            item.maxStack = maxStack;
            item.icon = icon;
            item.tooltipDescription = tooltipDescription;
        }

        private void ApplyTypeData(ItemData item)
        {
            // Clear type-specific defaults first via prune after assign — set only what this type needs.
            item.healthRestore = 0f;
            item.energyRestore = 0f;
            item.staminaRestore = 0f;
            item.oxygenRestore = 0f;
            item.componentCategory = ComponentCategory.None;
            item.unlocksInventoryStorageRow = false;
            item.isMiningTool = false;
            item.deployedPrefab = null;
            item.toolType = ToolType.None;

            switch (itemType)
            {
                case ItemType.Consumable:
                    item.healthRestore = healthRestore;
                    item.energyRestore = energyRestore;
                    item.staminaRestore = staminaRestore;
                    item.oxygenRestore = oxygenRestore;
                    item.unlocksInventoryStorageRow = unlocksInventoryStorageRow;
                    break;

                case ItemType.Resource:
                    item.componentCategory = componentCategory;
                    item.unlocksInventoryStorageRow = unlocksInventoryStorageRow;
                    break;

                case ItemType.MeleeWeapon:
                    ApplyEquipmentShared(item, includeSwing: true);
                    item.meleeDamage = meleeDamage;
                    item.meleeDamageRandomRange = meleeDamageRandomRange;
                    item.criticalChance = criticalChance;
                    item.criticalDamageMultiplier = criticalDamageMultiplier;
                    item.meleeRange = meleeRange;
                    item.meleeCooldown = meleeCooldown;
                    item.meleeStaminaCost = meleeStaminaCost;
                    item.gatherPower = gatherPower;
                    item.attackTrigger = attackTrigger;
                    break;

                case ItemType.RangedWeapon:
                    ApplyEquipmentShared(item, includeSwing: false);
                    item.isMiningTool = isMiningTool;
                    if (isMiningTool)
                    {
                        item.miningPassesRequired = miningPassesRequired;
                        item.miningDropMin = miningDropMin;
                        item.miningDropMax = miningDropMax;
                        item.miningPassDuration = miningPassDuration;
                        item.miningChargeDrainPerSecond = miningChargeDrainPerSecond;
                        item.miningChargePerPlasmaFuel = miningChargePerPlasmaFuel;
                    }
                    else
                    {
                        item.rangedDamage = rangedDamage;
                        item.rangedDamageRandomRange = rangedDamageRandomRange;
                        item.rangedRange = rangedRange;
                        item.projectileSpeed = projectileSpeed;
                        item.projectileSpreadDegrees = projectileSpreadDegrees;
                        item.weaponAccuracy = weaponAccuracy;
                        item.fireRate = fireRate;
                        item.magazineSize = magazineSize;
                        item.reloadTimeSeconds = reloadTimeSeconds;
                        item.defaultAmmoType = defaultAmmoType;
                        item.compatibleAmmoTypes = new[] { defaultAmmoType };
                        item.defaultAmmoItem = defaultAmmoItem;
                        item.projectilePrefab = projectilePrefab;
                        item.muzzleSocketName = muzzleSocketName;
                    }
                    break;

                case ItemType.Ammo:
                    item.ammoType = ammoType;
                    item.ammoPerPickup = ammoPerPickup;
                    item.ammoPickupGrant = ammoPickupGrant;
                    item.rangedDamage = rangedDamage;
                    item.rangedDamageRandomRange = rangedDamageRandomRange;
                    item.rangedRange = rangedRange;
                    item.projectileSpeed = projectileSpeed;
                    item.projectileSpreadDegrees = projectileSpreadDegrees;
                    item.weaponAccuracy = weaponAccuracy;
                    item.projectilePrefab = projectilePrefab;
                    item.isHitscanBeam = isHitscanBeam;
                    item.splashRadius = splashRadius;
                    break;

                case ItemType.Tool:
                    item.heldPrefab = heldPrefab;
                    item.equipSocketName = equipSocketName;
                    item.toolType = toolType;
                    item.toolRange = toolRange;
                    if (toolType == ToolType.Scanner || toolType == ToolType.Binoculars)
                    {
                        item.scanRange = scanRange;
                        item.opticsZoomFov = opticsZoomFov;
                        item.opticsMinZoomFov = opticsMinZoomFov;
                        item.opticsMaxZoomFov = opticsMaxZoomFov;
                    }
                    break;

                case ItemType.Vehicle:
                    item.deployedPrefab = deployedPrefab;
                    break;

                case ItemType.Quest:
                    break;
            }
        }

        private void ApplyEquipmentShared(ItemData item, bool includeSwing)
        {
            item.weaponGrip = weaponGrip;
            item.heldPrefab = heldPrefab;
            item.equipSocketName = equipSocketName;
            item.invectorWeaponPrefab = invectorWeaponPrefab;
            item.invectorWeaponId = invectorWeaponId;
            if (includeSwing)
                item.swingEulerAngles = swingEulerAngles;
        }

        private void CreateWorldPickup(ItemData item, string safeName)
        {
            GameObject instance = Object.Instantiate(worldPrefabTemplate);
            instance.name = safeName + "_World";

            Collider collider = instance.GetComponentInChildren<Collider>();
            if (collider == null)
            {
                BoxCollider box = instance.AddComponent<BoxCollider>();
                box.isTrigger = true;
            }
            else
            {
                collider.isTrigger = true;
            }

            ItemPickup pickup = instance.GetComponent<ItemPickup>();
            if (pickup == null)
                pickup = instance.AddComponent<ItemPickup>();

            pickup.itemData = item;
            pickup.amount = 1;

            string prefabPath = $"{ProjectAssetPaths.PrefabsItemsWorld}/{safeName}_World.prefab";
            PrefabUtility.SaveAsPrefabAsset(instance, prefabPath);
            Object.DestroyImmediate(instance);

            item.worldPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
            EditorUtility.SetDirty(item);
        }
    }
}

